window.ANTZ_I18N = {"meta":{"lang":"pt","source":false,"reviewed":false,"translator":"machine (Claude)"},"ui":{"brand.title":"Guia de Integração Antz","brand.label":"Guia de Integração","brand.home":"Antz Systems, início","meta.description":"Um guia curto e visual da plataforma Antz para equipes de cuidado animal.","nav.primary":"Principal","nav.menu":"Menu","nav.modules":"Módulos","nav.why":"Por que a Antz","nav.start":"Primeiros passos","nav.faq":"Perguntas frequentes","nav.cta":"Pronto para começar?","nav.search":"Pesquisar no guia","nav.searchTip":"Pesquisar (Ctrl/Cmd + K)","footer.tagline":"Bons dados = boas análises = animais saudáveis","footer.explore":"Explorar","footer.talk":"Fale conosco","footer.rights":"© 2026 Antz Systems. Todos os direitos reservados.","lang.label":"Idioma","lang.note":"Esta página foi traduzida automaticamente e aguarda revisão de um falante nativo.","lang.english":"Ver em inglês","lang.dismiss":"Fechar","lang.inApp":"No aplicativo: {x}","hero.title":"Uma plataforma para todos os animais sob seus cuidados","hero.sub":"Registros, operações diárias e trabalho em equipe em todas as suas unidades. Encontre qualquer tarefa na Antz, com as telas reais.","hero.areas":"{n} áreas de trabalho","hero.devices":"Celular e web","search.label":"Pesquisar módulos e funcionalidades","search.cue":"Pesquisar {x}","search.clear":"Limpar pesquisa","search.short":"Digite pelo menos duas letras para pesquisar em todos os módulos e funcionalidades.","search.top":"Principais resultados","search.none":"Nenhum resultado para “{q}”. Tente “animal”, “ovo” ou “relatório”.","start.label":"Comece aqui","kit.objective.eyebrow":"Comece aqui","kit.objective.more":"Ler o objetivo","kit.objective.kicker":"Por que realizamos este treinamento","kit.objective.photo":"Um tratador alimentando um pequeno animal em seu recinto","kit.platform.eyebrow":"A plataforma","kit.platform.more":"Conheça a Antz","kit.platform.why":"Por que usar este aplicativo","kit.platform.photo":"Uma mão segurando um celular com o aplicativo Antz Systems","kit.start.eyebrow":"Fluxo de integração","kit.start.more":"Iniciar o guia","kit.start.features":"Funcionalidades","day.title":"Como é o seu primeiro dia na Antz","day.lede":"Quatro etapas levam sua equipe do primeiro login ao uso diário.","day.1":"Entre no seu espaço de trabalho","day.2":"Oriente-se na plataforma","day.3":"Configure seus dados mestres","day.4":"Dê a cada pessoa o acesso certo","day.4.desc":"Crie perfis que correspondam à sua organização e ative as permissões módulo por módulo, para que cada pessoa veja o que o seu trabalho exige.","modules.eyebrow":"O que há dentro","modules.title":"Explore os módulos","modules.lede":"Toque em qualquer cartão para abrir o guia correspondente, com todas as funcionalidades e suas telas.","modules.filter":"Filtrar módulos por área","modules.all":"Todos","modules.count":"{n} módulos","modules.features":"{n} funcionalidades","spot.tag":"Fluxo em destaque","spot.link":"Ver {x} em detalhes","cta.title":"Travou em alguma tarefa?","cta.text":"Cada módulo tem suas funcionalidades e telas reais neste guia. Continue de onde parou ou fale conosco e nós ajudaremos.","cta.back":"Voltar aos módulos","cta.or":"Dúvidas? Escreva para {email}","faq.eyebrow":"Perguntas frequentes","faq.title":"As primeiras perguntas das equipes","faq.q1":"O que é a Antz?","faq.q2":"Funciona em celulares e computadores?","faq.a2":"Sim. O aplicativo móvel cobre o trabalho em campo, como notas, tratamentos, transferências e registros de ovos. O aplicativo web cobre o trabalho de escritório, como o sistema hospitalar, a configuração do berçário, os relatórios e o estoque da farmácia. As atualizações aparecem em tempo real no celular, no tablet e no computador.","faq.q3":"Podemos controlar quem vê o quê?","faq.a3":"Sim. O acesso é baseado em perfis. Você cria os perfis que sua organização usa, por exemplo Zoólogo, e ativa as permissões módulo por módulo.","faq.q4":"Temos mais de uma unidade. Isso funciona?","faq.a4":"A Antz mantém os dados de todas as unidades e departamentos em um só lugar. Os alojamentos são organizados por unidade, setor e recinto, e as movimentações entre unidades passam por aprovação e por uma liberação de saída pela segurança.","faq.q5":"Como começamos?","faq.a5":"Comece pelo guia Primeiros passos e depois abra os módulos que o seu perfil utiliza. Se algo não estiver claro, escreva para hello@antz.systems.","pager.prev":"Anterior","pager.next":"Próximo","pager.modules":"Explore os módulos","pager.pages":"Página anterior e próxima","pager.moduleNav":"Módulo anterior e próximo","mod.tabs":"Áreas e módulos","mod.features":"Funcionalidades","mod.hintClick":"Clique em uma funcionalidade para abrir sua tela","mod.hintTap":"Toque em uma funcionalidade para abrir sua tela","mod.soon":"As telas deste módulo estarão disponíveis em breve","mod.zoom":"Toque na tela para ampliar","win.prev":"Funcionalidade anterior","win.next":"Próxima funcionalidade","win.close":"Fechar","win.count":"Funcionalidade {i} de {n}","win.soon":"Tela disponível em breve","gal.label":"Telas de {x}","gal.close":"Fechar galeria","gal.screen":"Tela {i}","gal.hint":"Faça pinça ou toque duas vezes para ampliar · Deslize para navegar"},"tracks":{"records":{"label":"Registros e Comunicação","desc":"As funções mais leves e de uso mais frequente: notas, chat e configuração de usuários."},"animal":{"label":"Registros e Movimentação de Animais","desc":"Coleção, alojamento e cada movimentação que um animal faz dentro do zoológico."},"medical":{"label":"Médico e Tratamento","desc":"Registros, prescrições, tratamentos e o sistema de informação hospitalar."},"mortality":{"label":"Mortalidade e Ciclo de Vida","desc":"Mortalidade, necropsia e gestão do ciclo de vida dos ovos."},"operations":{"label":"Operações e Supervisão","desc":"Comunicados, central de ajuda, segurança, relatórios e conformidade."}},"modules":{"objective-of-this-kit":{"title":"Objetivo deste kit","intro":"A integração tem quatro objetivos: deixar cada membro da equipe confiante nas atividades do dia a dia, garantir a adoção da plataforma em todos os perfis, identificar lacunas para que possamos melhorar e padronizar a forma como os registros são mantidos em todas as unidades.","features":[{"title":"Desenvolvimento de competências","desc":"Ampliar o conhecimento da equipe e as habilidades práticas necessárias para operações eficazes no zoológico, o cuidado dos animais e o uso confiante da plataforma Antz.","alt":""},{"title":"Adoção do sistema","desc":"Familiarizar os usuários com cada módulo do aplicativo e dar confiança para realizar as ações principais, como registrar, revisar e aprovar, sem supervisão.","alt":""},{"title":"Melhoria contínua","desc":"Identificar as lacunas, esclarecer as dúvidas e usar o aprendizado baseado em feedback para aprimorar os fluxos de trabalho e o comportamento dos módulos ao longo do tempo.","alt":""},{"title":"Padronização","desc":"Protocolos consistentes entre equipes e unidades, com o mesmo comportamento dos módulos de Solicitações, Mortalidade, Ovos e Dieta, para que todos os registros sigam o mesmo padrão.","alt":""}]},"what-is-antz-systems":{"title":"O que é a Antz Systems?","intro":"A Antz é a sua plataforma completa para registros de animais, operações diárias e colaboração em equipe. Ela centraliza os dados de todas as unidades e departamentos, para que cada ação fique documentada, transparente e rastreável.","features":[{"title":"Melhores registros, melhores cuidados","desc":"Cada detalhe preciso, acessível, com data e hora e vinculado ao animal certo.","alt":""},{"title":"Trabalho em equipe simplificado","desc":"Sem lacunas entre veterinários, tratadores e gestores: todos no mesmo registro.","alt":""},{"title":"Segura desde a concepção","desc":"O acesso baseado em perfis protege dados sensíveis e alinha os direitos ao organograma.","alt":""},{"title":"Decisões na palma da mão","desc":"Relatórios mais rápidos e análises prontas para conformidade, sem depender de planilhas.","alt":""},{"title":"Operações sem papel","desc":"Reduza erros de transcrição e economize tempo em todos os turnos.","alt":""},{"title":"Atualizações em tempo real","desc":"Acesse as informações mais recentes a qualquer hora e em qualquer lugar, no celular, no tablet e no computador.","alt":""}],"shots":{"assets/shots/app-welcome-c.jpg":"Tela de boas-vindas do aplicativo Antz Systems: bons dados + boas análises = animais saudáveis."}},"getting-started":{"title":"Primeiros passos","intro":"O guia Primeiros passos apresenta a finalidade do aplicativo e conduz os novos usuários pelas etapas essenciais para configurar o perfil, explorar as principais funcionalidades e navegar pela plataforma com eficiência.","features":[{"title":"Acesso e espaços de trabalho","desc":"Faça login com segurança e acesse o seu ambiente de trabalho designado.","alt":"Tela inicial da Antz Systems: barra de pesquisa, Administração pendente (“Pending Administration”), análises do mês com Natalidade/Mortalidade e um cartão de comunicado"},{"title":"Navegação e interface","desc":"Use o feed da tela inicial para ver atualizações e atalhos de navegação rápida, e o painel inferior para as ferramentas principais.","alt":""},{"title":"Necropsia / Administração / Alocação pendentes","desc":"Animais aguardando necropsia, documentação administrativa e os procedimentos seguintes de alocação ou destinação antes do encerramento definitivo dos registros.","alt":""},{"title":"Configuração mestre e módulos","desc":"Configure os dados mestres e explore módulos como Registros Médicos, Alojamento, Ovos, Dieta e Gestão de Animais.","alt":""},{"title":"Personalização","desc":"Gerencie notas, atualize seu perfil e ajuste as preferências de idioma.","alt":""},{"title":"Permissões","desc":"Entenda os níveis de acesso necessários para operações seguras.","alt":""}]},"notes-module":{"title":"Módulo de Notas","intro":"O Módulo de Notas centraliza o registro de atualizações diárias, observações e ocorrências vinculadas a animais, recintos e operações. Ele garante entradas estruturadas e com data e hora, uma coordenação fluida da equipe e uma recuperação rápida por filtros e etiquetas, e apoia cuidados consistentes, a detecção precoce de problemas e a conformidade.","summary":"Centraliza o registro de atualizações diárias, observações e ocorrências de animais, recintos e operações","features":[{"title":"Adicionar e ver notas","desc":"Crie novas notas e acesse as notas feitas por você ou por outros usuários autorizados.","alt":"Formulário de nova nota: tipo de nota, notas, notificar membros, entidade, anexos, prioridade"},{"title":"Editar, ouvir e excluir","desc":"Modifique, ouça em áudio ou remova notas de acordo com as permissões atribuídas.","alt":"Detalhe da nota: Médica, Doente, Tigre AID 425990, com editar e favoritar"},{"title":"Prioridade","desc":"Defina o nível de urgência para que as pessoas certas vejam primeiro.","alt":"Detalhe da nota com a marca de prioridade no canto superior direito"},{"title":"Tipo de nota e vínculos","desc":"Categorize, vincule a animais, recintos ou setores e anexe documentos.","alt":"Detalhe da nota com o cartão da entidade animal vinculada, Tigre AID 425990"},{"title":"Visibilidade","desc":"As notas aparecem automaticamente nas páginas do animal, da unidade ou do setor correspondente.","alt":"Aba Notas da página da unidade: nota de higiene exibida em Central Reserve Kingdom"},{"title":"Notificações e colaboração","desc":"Notifique os membros marcados; curtidas e comentários mantêm o foco.","alt":"Nota com curtida, membro marcado Dr. Cloomy Fernandes, 1 comentário"},{"title":"Filtros e pesquisa","desc":"Filtre por palavras-chave, etiquetas, autor ou entidade vinculada.","alt":"Lista de notas com as abas Minhas notas (“My Notes”) / Todas as notas (“All Notes”) e Filtros"}]},"chat-module":{"title":"Módulo de Chat","intro":"O Módulo de Chat é um canal de comunicação dentro do aplicativo, com mensagens individuais e em grupo, compartilhamento de mídia e notificações em tempo real. Assim, todas as conversas de trabalho, atualizações e a coordenação ficam protegidas dentro da plataforma, em vez de espalhadas por celulares pessoais e e-mails.","summary":"Mensagens individuais e em grupo, compartilhamento de mídia e notificações em tempo real, com segurança dentro da plataforma","features":[{"title":"Mensagens individuais","desc":"Permite conversas individuais entre membros da equipe para uma comunicação e colaboração fluidas.","alt":"Conversa no chat da Antz Systems: coordenação da coleta de amostras de sangue entre a Dra. Neha e o biólogo Mayur"},{"title":"Mensagens em grupo","desc":"Crie um grupo para qualquer equipe, turno ou tarefa e converse em um só lugar.","alt":"Conversa no chat da Antz Systems: coordenação da coleta de amostras de sangue entre a Dra. Neha e o biólogo Mayur"},{"title":"Compartilhamento de mídia e documentos","desc":"Envie fotos, vídeos, laudos de laboratório e PDFs na própria conversa, sem precisar de aplicativos externos.","alt":"Conversa no chat da Antz Systems: coordenação da coleta de amostras de sangue entre a Dra. Neha e o biólogo Mayur"},{"title":"Notificações em tempo real","desc":"Receba notificações instantâneas diretamente no aplicativo sobre atualizações importantes.","alt":"Conversa no chat da Antz Systems: coordenação da coleta de amostras de sangue entre a Dra. Neha e o biólogo Mayur"},{"title":"Seguro e auditável","desc":"Todas as conversas ficam dentro da Antz, com o histórico preservado.","alt":"Conversa no chat da Antz Systems: coordenação da coleta de amostras de sangue entre a Dra. Neha e o biólogo Mayur"},{"title":"Pesquisa e filtros","desc":"Encontre mensagens por palavra-chave, remetente ou entidade vinculada.","alt":"Conversa no chat da Antz Systems: coordenação da coleta de amostras de sangue entre a Dra. Neha e o biólogo Mayur"}]},"user-management":{"title":"Gestão de Usuários","intro":"O Módulo de Usuários permite a gestão segura e centralizada de contas, perfis e permissões. Ele agiliza a integração de usuários, garante a segurança dos dados e alinha os direitos de acesso aos cargos da organização, mantendo registros de atividade detalhados para fins de responsabilização.","summary":"Permite a gestão segura e centralizada de contas, perfis e permissões","features":[{"title":"Criação e gestão de perfis","desc":"Gerencie nome, contato, matrícula, data de nascimento e tipo sanguíneo.","alt":"Formulário de informações básicas para adicionar usuário: nome, nome de usuário, e-mail, senha, celular, matrícula"},{"title":"Perfis e permissões","desc":"Atribua perfis e gerencie os direitos de acesso por módulo.","alt":"Editar permissões: perfil Veterinário com caixas de seleção de acesso por módulo"},{"title":"Controle de acesso","desc":"Restrinja por unidade/setor, ative contas e defina o encerramento automático da sessão.","alt":"Perfil do usuário com o menu Desativar, Redefinir senha, Redefinir código de acesso"},{"title":"Login e recuperação","desc":"Login seguro com recuperação por código OTP via SMS ou WhatsApp.","alt":"Tela Redefinir senha / Esqueci a senha com campo de nome de usuário ou e-mail"},{"title":"Acompanhamento de atividades","desc":"Veja o último login e os detalhes dos dispositivos, e desative dispositivos.","alt":"Aba Diário (“Journal”) do perfil do usuário: registro de atividades com o horário da última atividade"},{"title":"Informações adicionais","desc":"Registre formação, histórico profissional e envie documentos de identidade.","alt":"Aba Documentos de identidade do perfil do usuário: cartão Aadhaar com anexo"}]},"collection":{"title":"Coleção","intro":"O Módulo de Coleção foi criado para gerenciar e documentar todos os aspectos da coleção de animais de uma instituição, servindo como central para registrar espécies, acompanhar animais individuais e manter históricos taxonômicos precisos.","summary":"Gerencia e documenta todos os aspectos da coleção de animais da instituição: espécies, animais individuais e históricos taxonômicos","features":[{"title":"Visão geral da coleção","desc":"Taxonomia, população por sexo, contagens de entradas/nascimentos, com pesquisa.","alt":"Visão geral das Coleções: indicadores de espécies e população, entradas e nascimentos, e classes taxonómicas com contagens"},{"title":"Gestão de espécies","desc":"Contagens, morfos, dados médicos, dieta, mortalidade e situação da necropsia.","alt":"Detalhe da espécie Tigre com população, unidades, setores e recintos"},{"title":"Adicionar avaliação em lote","desc":"Entrada de dados em grupo com navegação sequencial e filtros.","alt":"Lista de avaliação da espécie com a condição corporal de cada animal"}]},"housing":{"title":"Alojamento","intro":"O módulo de Alojamento organiza os habitats dos animais em suas unidades, setores e recintos, para que cada animal tenha um local conhecido e cada alteração seja registrada. O acesso em cada nível é baseado em permissões.","summary":"Organiza os habitats dos animais em unidades, setores e recintos, com cada alteração registrada","features":[{"title":"Administração de unidades","desc":"Adicione ou edite unidades com permissões baseadas em perfis, para um acesso seguro e estruturado.","alt":"Detalhe da unidade: Wildlife Zoological Park com contagens de espécies/animais/setores e lista de recintos"},{"title":"Administração de setores","desc":"Adicione ou edite setores dentro do zoológico, com controles baseados em permissões para uma administração segura.","alt":"Detalhe do setor: Animal Kingdom com contagens de espécies/animais/recintos e lista de recintos"},{"title":"Administração de recintos","desc":"Adicione ou edite recintos e acompanhe cada um para uma supervisão eficiente dos animais e dos dados.","alt":"Lista de recintos: Gentle Giants, Herbivores, The Tiger Trail com contagens de animais"}]},"animal-management":{"title":"Gestão de Animais","intro":"O Módulo de Animais reúne todos os registros de animais em um só lugar, sejam ativos, transferidos, desaparecidos ou excluídos, com perfis, fluxos de entrada no acervo e um layout simples organizado em abas.","summary":"Reúne todos os registros de animais em um só lugar","features":[{"title":"Pesquisar animais","desc":"Adicione novos animais por fluxos guiados vinculados a alojamento, dieta e dados médicos.","alt":"Lista de animais com contagens: Todos os animais 2828, Transferidos 11, Excluídos 27, Desaparecidos/Fugidos 8"},{"title":"Adicionados recentemente","desc":"Animais recém-adicionados ao sistema, no topo do feed.","alt":"Lista Adicionados recentemente: lóris-lento, elefante-africano, tigre, crocodilo-de-água-salgada, casuar"},{"title":"Todos os animais","desc":"O banco de dados completo, pesquisável, filtrável e exportável.","alt":"Lista Todos os animais: coelho-europeu, casuar, hipopótamo-comum, tigre, elefante-asiático"},{"title":"Transferidos","desc":"Animais movimentados entre unidades ou recintos, com a procedência completa.","alt":"Lista de animais transferidos: tigre, leão, lóris-lento, urso-negro-americano, leão"},{"title":"Excluídos","desc":"Registros de animais removidos, mantidos para auditoria e possível reversão.","alt":"Lista de animais excluídos"},{"title":"Desaparecidos / fugidos","desc":"Animais marcados como desaparecidos ou fugidos, vinculados ao relatório de ocorrência.","alt":"Lista de animais desaparecidos/fugidos: urso-negro-americano, casuar, crocodilo-de-água-salgada, hipopótamo-comum, tigre"}]},"tags-hub":{"title":"Central de Etiquetas","intro":"O Módulo Central de Etiquetas ajuda você a organizar e categorizar diferentes entidades (unidades, setores, recintos, animais) na plataforma Antz usando etiquetas personalizáveis com base na situação atual, na finalidade ou em qualquer classificação personalizada.","summary":"Organiza e categoriza unidades, setores, recintos e animais com etiquetas personalizáveis","features":[{"title":"Tipos de etiqueta — Pública, Privada, Sistema","desc":"Organize e categorize entidades usando etiquetas Públicas, Privadas e definidas pelo Sistema.","alt":"Minha Central de Etiquetas: pesquisa, contagens de etiquetas Total/Sistema/Públicas/Privadas e etiquetas Públicas e Privadas"},{"title":"Pesquisa e filtros","desc":"Encontre etiquetas rapidamente usando as opções de pesquisa e filtro.","alt":"Minha Central de Etiquetas: pesquisa, contagens de etiquetas Total/Sistema/Públicas/Privadas e etiquetas Públicas e Privadas"},{"title":"Criar etiquetas","desc":"Crie novas etiquetas Públicas ou Privadas conforme suas necessidades.","alt":"Criar nova etiqueta: nome da etiqueta, categoria, perfis a notificar, notas e botão Criar etiqueta (“Create Tag”)"},{"title":"Editar e excluir etiquetas","desc":"Modifique o nome, a cor ou a visibilidade das etiquetas Privadas, ou remova definitivamente as etiquetas que não são mais necessárias.","alt":"Painel Detalhes da etiqueta: categoria, tipo, criada por, notas, entidades etiquetadas, com as ações Editar e Excluir"},{"title":"Atribuir etiquetas Públicas e Privadas","desc":"Aplique etiquetas a unidades, setores, recintos ou animais para facilitar a organização.","alt":"Separador Etiquetas no perfil de um animal: etiquetas públicas e privadas, com As minhas etiquetas e Etiquetas de outros, e um botão + para adicionar uma etiqueta"},{"title":"Remover etiquetas atribuídas","desc":"Remova etiquetas de unidades, setores, recintos ou animais sempre que necessário.","alt":"Confirmação Remover etiqueta: Tem certeza de que deseja remover estas etiquetas desta unidade? Cancelar ou Remover"},{"title":"Visibilidade","desc":"Controle se as etiquetas Privadas permanecem pessoais ou ficam visíveis para todos os usuários.","alt":"Detalhes de uma etiqueta Privada: tipo Privada (visível para todos) com a opção Tornar esta etiqueta visível para todos"},{"title":"Entidades etiquetadas","desc":"Veja todas as unidades, setores, recintos, espécies e animais associados a uma etiqueta selecionada.","alt":"Separador Entidades da etiqueta Desparasitação pendente: 12 entidades etiquetadas, uma lista pesquisável de recintos, secções, espécies e animais"}]},"animal-transfer":{"title":"Transferência de Animais","intro":"Registra e gerencia todas as movimentações de animais dentro e fora da organização, acompanhando solicitações, aprovações e alocações para uma realocação segura e bem documentada.","summary":"Registra e gerencia todas as movimentações de animais dentro e fora da organização","features":[{"title":"Tipos de transferência","desc":"Transferências internas, entre unidades e externas.","alt":"Caixa de diálogo para escolher o tipo de transferência: interna, entre locais e externa"},{"title":"Aprovação","desc":"Autorização das autoridades designadas da unidade.","alt":"Transferência entre locais a aguardar aprovação, com Aprovar e Rejeitar"},{"title":"Cancelar / rejeitar","desc":"Cancele ou rejeite solicitações e reinicie-as quando necessário.","alt":"Opção Cancelar transferência no menu da transferência"},{"title":"Entrada / saída pela segurança","desc":"Entrada e saída controladas para transferências entre unidades e externas.","alt":"Autorização de segurança pendente, com a ação Saída de segurança"},{"title":"Alocação","desc":"Na chegada, aloque o animal em um recinto e notifique a equipe.","alt":"Estado Animais recebidos, com a ação Atribuir recintos"},{"title":"Registro de transferências","desc":"Histórico completo de status com data, hora e usuários.","alt":"Cronologia da transferência que termina em Transferência concluída"}]},"approvals":{"title":"Aprovações","intro":"Gerencia e acompanha as solicitações de transferência de animais, dando visibilidade às solicitações pendentes, aprovadas e rejeitadas. Agiliza o processo de revisão, garante a autorização adequada e mantém um registro transparente das decisões de transferência para fins de responsabilização e conformidade.","summary":"Gerencia e acompanha solicitações de transferência de animais: pendentes, aprovadas e rejeitadas","features":[{"title":"Acompanhar status","desc":"Aguardando aprovação, Aprovada, Rejeitada, Permitir saída/entrada, Alocada.","alt":"Lista de aprovações de transferência com selos de status"},{"title":"Revisar solicitação","desc":"Veja todos os detalhes antes de aprovar.","alt":"Detalhes da solicitação de transferência para revisão"},{"title":"Aprovar / rejeitar","desc":"Autorize ou recuse com a devida justificativa.","alt":"Detalhe da solicitação de transferência com Aprovar (“Approve”) e Rejeitar (“Reject”)"},{"title":"Redefinir aprovação","desc":"Reabra ou atualize uma solicitação aprovada anteriormente.","alt":"Transferência aprovada com a opção Redefinir aprovação (“Reset Approval”)"},{"title":"Cancelar transferência","desc":"Cancele antes ou depois da aprovação, com o motivo registrado.","alt":"Detalhe da solicitação com a opção Cancelar transferência (“Cancel Transfer”)"}]},"missing-escaped-animal":{"title":"Animal Desaparecido / Fugido","intro":"Permite comunicar, acompanhar e resolver rapidamente casos de animais desaparecidos ou fugidos, com entradas datadas vinculadas aos seus perfis para fins de responsabilização e uma resposta coordenada entre segurança, veterinários e gestão.","summary":"Comunicação, acompanhamento e resolução rápidos de animais desaparecidos ou fugidos","features":[{"title":"Relato de ocorrência e anexos","desc":"Registre detalhes e ações, e envie imagens ou vídeos.","alt":"Formulário para relatar animais fugidos/desaparecidos"},{"title":"Editar relatório","desc":"Atualize ou modifique o relatório de ocorrência conforme a situação evolui.","alt":"Linha do tempo da ocorrência, animal desaparecido"},{"title":"Relato de recuperação","desc":"Registre os detalhes da recuperação e sinalize correções.","alt":"Formulário para relatar animal encontrado"},{"title":"Registro de eventos e rastreabilidade","desc":"Registre cada ação, em ordem, na linha do tempo do animal.","alt":"Menu com a opção de marcar o desaparecimento como relato incorreto"},{"title":"Visibilidade","desc":"Marcado como desaparecido no perfil do animal.","alt":"Perfil do animal com selo de desaparecido e QR"}]},"medical-records":{"title":"Registros Médicos","intro":"O Módulo Médico ajuda a registrar, acompanhar e gerenciar os dados de saúde dos animais, incluindo diagnósticos, prescrições e tratamentos. Ele favorece cuidados oportunos, históricos médicos organizados e a coordenação entre as equipes veterinárias, para um melhor bem-estar animal.","summary":"Ajuda a registrar, acompanhar e gerenciar os dados de saúde dos animais","features":[{"title":"Criação de registros","desc":"Vários fluxos para adicionar registros individuais, em lote, em grupo, programados (vacinação, vermifugação, suplemento) ou diretos (administração, prescrição, vacinação, vermifugação, suplemento) e solicitações de exames laboratoriais, com registro exato de data e hora.","alt":"Menu de criação de registros: registro médico individual, em grupo, em lote, solicitação de exame em pool, administração direta, prescrição, vacinação, vermifugação, suplementos"},{"title":"Visão geral do registro","desc":"Um resumo rápido com os dados do médico e o perfil do animal, para fácil consulta.","alt":"Visão geral do registro médico MED-09501: médico, perfil do animal, tipo de caso e sintomas"},{"title":"Favoritar, editar, excluir, baixar","desc":"Modifique ou remova registros; os relatórios baixados são enviados para o e-mail cadastrado.","alt":"Registro médico MED-08805 com os ícones de favoritar, editar e mais opções"},{"title":"Linha do tempo do diário médico","desc":"Registro cronológico de todas as ações de inclusão e edição, com rastreabilidade completa.","alt":"Diário médico: registro cronológico das ações nos registros médicos, com data e hora"},{"title":"Reatribuir registros","desc":"Médicos podem reatribuir a si mesmos registros criados originalmente por outro veterinário.","alt":"Confirmação de reatribuição: Deseja reatribuir este registro médico a você? Sim / Não"}]},"symptoms-clinical-assessment-prescription":{"title":"Sintomas, Avaliação Clínica e Prescrição","intro":"A funcionalidade Sintomas, Avaliação Clínica e Prescrição oferece análises dos sintomas registrados, dos diagnósticos e dos tratamentos prescritos, ajudando os usuários a acompanhar tendências de saúde e apoiando decisões clínicas bem fundamentadas.","summary":"Análises de sintomas, diagnósticos e tratamentos prescritos para apoiar decisões clínicas","features":[{"title":"Tendências de sintomas","desc":"Analise os sintomas registrados com mais frequência entre as espécies e acompanhe sua ocorrência ao longo do tempo.","alt":"Análise de sintomas: 7 espécies, 7 por sintomas, lista classificada liderada por fezes anormais, postura anormal, muda anormal"},{"title":"Análises de avaliação clínica","desc":"Acompanhe as avaliações clínicas realizadas nos animais e identifique os diagnósticos ou condições registrados com mais frequência.","alt":"Análise de avaliação clínica: 20 espécies, 35 avaliações, lideradas por doença hepática, cárie dentária, problemas gastrointestinais"},{"title":"Análise de prescrições","desc":"Veja os medicamentos mais prescritos e os padrões de tratamento por espécie e por caso.","alt":"Análise de prescrições: 7 espécies, 7 prescrições, lideradas por Aculife, Fluvac Innovator, Dolo 650"},{"title":"Filtros e pesquisa","desc":"Refine os dados por período, unidade, espécie e outros critérios relevantes.","alt":"Filtrar por período: hoje, ontem, últimos 7 dias, este mês, últimos 3 meses, últimos 6 meses, todo o período"}]},"administer-medicine":{"title":"Administrar Medicamentos","intro":"O Módulo de Administração complementa os Registros Médicos ao transformar prescrições em fluxos de tratamento práticos, permitindo a prestação de cuidados em tempo real a animais individuais ou em lote, em campo ou no hospital.","summary":"Complementa os Registros Médicos transformando prescrições em fluxos de tratamento práticos","features":[{"title":"Registro rápido","desc":"Crie um registro de administração direta para uma data escolhida sem preencher um registro médico completo.","alt":"Tela de administração: faixa de datas, abas Registros de animais / de grupos, blocos de status Administrado / Pulado / Interrompido / Pendente, com o botão de adição rápida em destaque"},{"title":"Pesquisa e filtros","desc":"Encontre registros rapidamente e restrinja a lista por data, entidade, espécie e substância controlada.","alt":"Tela de administração com Pesquisa, Filtros, seletor de mês e menu Todos os registros em destaque"},{"title":"Acompanhamento de status","desc":"Veja os tratamentos por data em quatro abas: Pendente, Administrado, Pulado, Interrompido.","alt":"Tela de administração com as abas de status Administrado, Pulado, Interrompido e Pendente em destaque"},{"title":"Ações em massa","desc":"Selecione vários registros para administrar ou pular medicamentos de uma só vez.","alt":"Tela de administração com Selecionar tudo e o botão Administrar (“Administer”) em destaque após selecionar registros"},{"title":"Detalhes da prescrição","desc":"Veja todas as informações, dosagem, número do lote e animal vinculado, no momento da administração.","alt":"Tela de prescrição com horários, frequência, duração e via de administração em destaque"},{"title":"Registro de dose única","desc":"Registre doses individuais com horário, número do lote e observações.","alt":"Tela de administração com um cartão de grupo de dose única e sua caixa de seleção em destaque"},{"title":"Visão geral na tela inicial","desc":"Veja o número de tratamentos pendentes diretamente na tela inicial, para agir mais rápido.","alt":"Ecrã Administração pendente: 847 doses pendentes no total entre animais, medicamentos e substâncias controladas, por local"}],"shots":{"assets/shots/p20-bulk.png":"Ações em massa de administração: Selecionar tudo, um registro de animal selecionado e os botões Pulado / Administrar","assets/shots/p20-prescription.png":"Detalhes da prescrição: ID do caso, horários, frequência, duração, via de administração, animal vinculado e esquema de doses"}},"vaccination":{"title":"Vacinação","intro":"O Módulo de Vacinação gerencia todo o ciclo de vacinação dos animais, desde o agendamento e a administração direta até o acompanhamento das vacinações próximas, pendentes, puladas e concluídas. Ele garante tratamentos no prazo, registro exato da dosagem e rastreabilidade completa para a prevenção de doenças e a conformidade clínica.","summary":"Gerencia todo o ciclo de vacinação, do agendamento e da administração direta ao acompanhamento de cada situação","features":[{"title":"Visualizações por status","desc":"Vacinações organizadas em Próximas, Pendentes, Puladas, Concluídas e Interrompidas, para facilitar o acompanhamento.","alt":"Menu de vacinação: Próximas, Pendentes, Concluídas, Puladas, Vacinas interrompidas, Administração direta, Agendar vacinação"},{"title":"Gestão da vacinação","desc":"Agende uma vacinação ou registre diretamente uma vacina administrada, com datas e detalhes do medicamento definidos.","alt":"Agendar vacinação com animais selecionados, prescrição e notas clínicas"},{"title":"Registro da administração","desc":"Registra dosagem, número do lote, via de administração, observações e acompanhamento opcional.","alt":"Detalhes da vacinação concluída com ID do caso e número do lote"},{"title":"Pendentes e próximas","desc":"Exibe todas as vacinações agendadas por data e unidade, para evitar tratamentos esquecidos.","alt":"Vacinações pendentes agrupadas por espécie"},{"title":"Pular e interromper","desc":"Adie ou interrompa vacinações informando motivos obrigatórios e datas de acompanhamento.","alt":"Detalhes da vacinação pendente com as ações Administrar e Pulado"},{"title":"Acesso centrado no animal","desc":"Os registros de vacinação podem ser vistos a partir de Animais, Alojamento ou Registros Médicos.","alt":"Aba Médico do perfil do animal mostrando vacinações pendentes, próximas e concluídas"}]},"deworming":{"title":"Vermifugação","intro":"O Módulo de Vermifugação apoia o registro e o acompanhamento sistemáticos dos tratamentos antiparasitários, garantindo administração no prazo, documentação adequada e acompanhamento claro de cada vermifugação de cada animal.","summary":"Registro e acompanhamento sistemáticos dos tratamentos antiparasitários","features":[{"title":"Visualizações por status","desc":"Vermifugações organizadas em Próximas, Pendentes, Puladas, Concluídas e Interrompidas, para facilitar o acompanhamento.","alt":"Menu de vermifugação: Próximas, Pendentes, Concluídas, Puladas, Vermifugações interrompidas, Administração direta, Agendar vermifugação"},{"title":"Gestão da vermifugação","desc":"Agende um tratamento ou registre diretamente o medicamento administrado, com datas e detalhes definidos.","alt":"Vermifugação direta com animal selecionado, prescrição e notas clínicas"},{"title":"Registro da administração","desc":"Registra dosagem, número do lote, via de administração, observações e acompanhamento opcional.","alt":"Adicionar medicamento: tipo de dose, quantidade, via de administração, acompanhamento e número do lote"},{"title":"Pendentes e próximas","desc":"Veja todas as vermifugações agendadas por data e unidade, em destaque para evitar tratamentos esquecidos.","alt":"Vermifugações pendentes agrupadas por espécie"},{"title":"Pular e interromper","desc":"Adie ou interrompa informando motivos obrigatórios e datas de acompanhamento.","alt":"Pular vermifugação: reagendar ou interromper, com motivo e pergunta sobre efeitos adversos"},{"title":"Acesso centrado no animal","desc":"Pode ser consultado a partir de Animais, Alojamento ou Registros Médicos.","alt":"Aba Médico do perfil do animal mostrando vermifugações pendentes, próximas e concluídas"}]},"supplements":{"title":"Suplementos","intro":"O Módulo de Suplementos apoia o registro e o acompanhamento sistemáticos dos programas de suplementação nutricional e alimentar, garantindo administração no prazo, documentação adequada e acompanhamento claro de cada suplemento dado a cada animal.","summary":"Registro e acompanhamento sistemáticos dos programas de suplementação nutricional e alimentar","features":[{"title":"Visualizações por status","desc":"Suplementos organizados em Próximos, Pendentes, Pulados, Concluídos e Interrompidos, para facilitar o acompanhamento.","alt":"Menu de suplementos: Próximos, Pendentes, Concluídos, Pulados, Suplementos interrompidos, Administração direta, Agendar suplementos"},{"title":"Gestão de suplementos","desc":"Agende ou registre diretamente os suplementos administrados, com datas e detalhes definidos.","alt":"Suplementação direta com animal selecionado, prescrição e notas clínicas"},{"title":"Registro da administração","desc":"Registra dosagem, número do lote, via de administração, observações e acompanhamento opcional.","alt":"Adicionar suplementos: tipo de dose, quantidade, via de administração, acompanhamento e número do lote"},{"title":"Pendentes e próximos","desc":"Todos os suplementos agendados por data e unidade, para evitar administrações esquecidas.","alt":"Suplementos pendentes agrupados por espécie"},{"title":"Pular e interromper","desc":"Adie ou interrompa informando motivos obrigatórios e datas de acompanhamento.","alt":"Pular suplementos: reagendar ou interromper, com motivo e data de acompanhamento"},{"title":"Acesso centrado no animal","desc":"Registros consultáveis a partir de Animais, Alojamento ou Registros Médicos.","alt":"Aba Médico do perfil do animal mostrando suplementos pendentes, próximos e concluídos"}]},"hospital-information-management-system-app":{"title":"Sistema de Gestão de Informações Hospitalares (App)","intro":"No aplicativo, a equipe solicita transferências de animais para o hospital e movimenta os pacientes com segurança, com ID médico, tipo de visita, finalidade, anexos e entrada e saída controladas pela segurança na unidade e no hospital.","summary":"A equipe solicita transferências de animais para o hospital e movimenta os pacientes com segurança","features":[{"title":"Solicitações de transferência","desc":"Solicite a hospitalização de animais, do local para o hospital, com ID médico, tipo de visita, finalidade e anexos.","alt":"Formulário de internação do animal: animal selecionado, ID médico (criar novo), campos Hospital e Tipo de visita, Enviar"},{"title":"Status da transferência","desc":"Acompanhe cada transferência por suas etapas ao nível do local: Pendente, Em trânsito, Aceita, Cancelada e Rejeitada.","alt":"Separador Transferência para o hospital no perfil do local: separadores Em trânsito, Aceites e Cancelados, com pedidos como HT29-00069 a aguardar aceitação"},{"title":"Entrada / saída pela segurança","desc":"Movimentação controlada dos pacientes, com entrada e saída registradas pela segurança na unidade e no hospital.","alt":"Transferência HT29-00068: saída de segurança pendente, com o botão Entrada de segurança"},{"title":"Ver relatórios de alta","desc":"Acesse os resumos de alta e o histórico de internações diretamente no aplicativo.","alt":"Registo médico MED29-18889 de um crocodilo-de-água-salgada: tipo de caso e um anexo Discharge_Summary.pdf adicionado pelo veterinário"}]},"hospital-information-management-system-web":{"title":"Sistema de Gestão de Informações Hospitalares (Web)","intro":"No console web, as equipes clínicas admitem e fazem a triagem dos pacientes que chegam, acompanham pacientes internados e ambulatoriais, registram tratamentos e dão alta aos animais, com rastreabilidade médica completa e relatórios para download.","summary":"Equipes clínicas admitem e triam pacientes, acompanham internados e ambulatoriais, registram tratamentos e dão alta","features":[{"title":"Admissão e triagem","desc":"Admita ou rejeite casos, com alocação de médico, sala e leito conforme as necessidades de tratamento.","alt":"Formulário de admissão do paciente: animal selecionado, motivo da visita, tipo de tratamento Ambulatorial / Internação, estado de saúde, Rejeitar e Admitir"},{"title":"Acompanhamento de internados / ambulatoriais","desc":"Configure e registre sinais vitais e observações programados, com linhas do tempo editáveis.","alt":"Lista de pacientes a receber: abas Pendentes e Rejeitados com os animais e o motivo da visita"},{"title":"Registros clínicos e de tratamento","desc":"Mantenha sintomas, notas clínicas, prescrições, anestesia, cirurgia e outros tratamentos em um só lugar.","alt":"Registro de internação MED29-17409: dados da admissão e abas Sintomas / Avaliação clínica / Prescrição"},{"title":"Alta","desc":"Dê alta aos animais de volta ao recinto ou registre o óbito com solicitação de necropsia e anexos.","alt":"Aba Alta: motivo da admissão, tipo de alta Mortalidade / Transferência para o recinto, Dar alta ao animal"},{"title":"Relatórios para download","desc":"Acesse resumos de alta, detalhes da internação atual e o histórico de visitas anteriores.","alt":"Lista de pacientes com alta, com duração, tipo de visita, veterinário responsável e ação de download"}]},"focus-hub":{"title":"Focus Hub","intro":"O Focus Hub é individual: mostra apenas os itens que cada usuário marcou como favoritos ou salvou nos marcadores. Ele reúne em um só lugar os animais e recintos favoritos e as notas, registros médicos e solicitações de exames marcados, para acesso rápido.","summary":"Seus animais e recintos favoritos e registros nos marcadores, em um só lugar para acesso rápido","features":[{"title":"Gerenciamento de pastas","desc":"Crie, renomeie e exclua pastas para organizar os itens salvos do jeito que você trabalha.","alt":"Aba Pastas do Meu Focus Hub com as pastas Animais, Feridos, Aves, Leão e Críticos"},{"title":"Animais e recintos favoritos","desc":"Marque, veja e remova animais e recintos dos seus Favoritos com um só toque.","alt":"Aba Favoritos do Meu Focus Hub com o seletor Animais/Recintos e uma lista de cartões de animais favoritos"},{"title":"Marcar registros","desc":"Adicione ou remova marcadores em notas, registros médicos ou solicitações de exames para consultá-los rapidamente depois.","alt":"Aba Marcadores do Meu Focus Hub com os filtros Notas, Registro médico e Solicitação de exame, e cartões de registros médicos marcados"}]},"mortality":{"title":"Mortalidade","intro":"O Módulo de Mortalidade permite registrar óbitos de animais de forma rápida e precisa, gerenciar os dados da necropsia e armazenar as evidências em um só lugar. Ele aumenta a transparência, agiliza a tomada de decisões, garante a conformidade e contribui para um melhor acompanhamento do bem-estar animal.","summary":"Registre óbitos de forma rápida e precisa, gerencie a necropsia e guarde as evidências em um só lugar","features":[{"title":"Painel de mortalidade","desc":"Totais de óbitos, espécies afetadas e causas.","alt":"Painel de mortalidade: 49 animais, 16 espécies e 6 causas, com os totais destacados"},{"title":"Listagens em várias visualizações","desc":"Registros por animal, espécie ou causa, vinculados aos perfis.","alt":"Registos de mortalidade por espécie, com contagens por sexo"},{"title":"Pesquisa avançada e filtros","desc":"Pesquise por espécie, causa, local, data ou palavra-chave.","alt":"Painel de mortalidade com Todos os dados, Todos os locais, pesquisa e ícone de filtro destacados"},{"title":"Registros de animais mortos","desc":"Detalhes completos do óbito: causa, ID, recinto, unidade, sexo.","alt":"Painel de mortalidade com o primeiro cartão de animal destacado"},{"title":"Editar registros","desc":"Edite os relatórios de mortalidade após o lançamento para mantê-los precisos.","alt":"Relatório de mortalidade com o ícone de lápis de edição destacado"},{"title":"Revogar registros","desc":"Revogue registros incorretos para restaurar o status ativo.","alt":"Relatório de mortalidade com o botão Revogar mortalidade destacado"},{"title":"Transferência de carcaça","desc":"Veja e acompanhe a movimentação de carcaças entre locais.","alt":"Lista de transferências de carcaças: 3 pendentes, 1 em trânsito, 8 concluídas"}],"shots":{"assets/shots/p27-mortality-4.jpg":"Cartão do registro de mortalidade — editar e revogar"}},"necropsy":{"title":"Necropsia","intro":"O Módulo de Necropsia documenta os exames post-mortem com observações detalhadas, achados por órgão e conclusões médicas. Ele apoia a análise precisa da causa da morte, padroniza os relatórios, garante o manejo oportuno das carcaças e atende às normas legais, de auditoria e veterinárias.","summary":"Documenta exames post-mortem com observações detalhadas, achados por órgão e conclusões médicas","features":[{"title":"Pesquisa e filtros","desc":"Pesquise por animal/espécie; filtre por unidade, data e prioridade.","alt":"Lista de necropsias: Recebidas, Pendentes, Rascunho e Concluídas, com os separadores Por animais/Por espécies e a barra de pesquisa destacados"},{"title":"Acompanhamento de status","desc":"Acompanhe as etapas: A receber, Pendente, Rascunho e Concluída.","alt":"Lista de necropsias com os separadores de estado Recebidas, Pendentes, Rascunho e Concluídas, com Pendentes selecionado"},{"title":"Cartão do animal e dados da solicitação","desc":"AID, espécie, local, causa, solicitante, prioridade.","alt":"Lista de necropsias com o primeiro cartão de pedido destacado"},{"title":"Transferência de carcaça","desc":"Veja as solicitações de transferência: Aguardando aceite, Recebidas.","alt":"Transferências de carcaças: separadores Aceitação pendente e Recebidas, com cartões de pedidos"},{"title":"Visualização detalhada da solicitação","desc":"Veja a solicitação de necropsia completa com os dados do animal e do óbito (causa, condição da carcaça, observações), atualize os registros, salve como rascunho ou envie quando estiver finalizada.","alt":"Detalhe do pedido de necropsia: relatório de mortalidade, causa suspeita, estado da carcaça e estado Pendente"},{"title":"Baixar relatório","desc":"Exporte relatórios ou rascunhos em PDF para arquivo ou uso offline.","alt":"Relatório de necropsia NPS29-00033 com o ícone de transferência destacado, adequação da carcaça e detalhes"},{"title":"Linha do tempo","desc":"Cada ação registrada com usuário, data e hora.","alt":"Cronologia: Necropsia concluída, Rascunho descartado, Guardado como rascunho, cada um com utilizador e hora"}]},"fetal-death":{"title":"Morte Fetal","intro":"O Módulo de Morte Fetal registra e gerencia ocorrências de morte fetal nos recintos, registrando causa, momento e dados dos animais relacionados. Ele apoia o cuidado veterinário, o acompanhamento da saúde reprodutiva, a análise de tendências e uma melhor gestão populacional.","summary":"Registra e gerencia ocorrências de morte fetal nos recintos","features":[{"title":"Adicionar registro de morte fetal","desc":"Registre novas ocorrências: causa, momento, parentesco, dados do animal.","alt":"Formulário Adicionar morte fetal com o recinto, a espécie/taxonomia e a filiação selecionados"},{"title":"Pesquisa e filtros","desc":"Pesquise por palavra-chave; filtre por unidade, data, natimorto ou aborto, espécie ou sexo.","alt":"Lista de mortes fetais com os filtros Todos os locais e Todos os dados, o separador Nado-morto e a barra de pesquisa destacados"},{"title":"Ver registros de óbito","desc":"Detalhes completos, dias desde o óbito, causa, ID, recinto, unidade, sexo.","alt":"Lista de mortes fetais com o primeiro cartão destacado"},{"title":"Exibição do cartão do animal","desc":"FID, espécie, descoberta, progenitores, unidade, sexo, responsável pelo registro.","alt":"Cartão de detalhe Resumo da morte fetal"},{"title":"Editar registro","desc":"Modifique um registro existente a partir do resumo, com trilha de auditoria.","alt":"Resumo da morte fetal com o lápis de edição destacado"},{"title":"Excluir registro","desc":"Remova um registro quando necessário, com trilha de auditoria completa.","alt":"Resumo da morte fetal com a opção Eliminar morte fetal destacada"}]},"egg-management-app":{"title":"Gestão de Ovos — App","intro":"O Módulo de Ovos acompanha todo o ciclo de vida dos ovos, da postura à eclosão ou à transferência para o berçário, garantindo registros precisos, atualizações em tempo real e rastreabilidade completa para uma melhor coordenação e responsabilização entre as equipes de ninho, berçário e incubatório.","summary":"Acompanha todo o ciclo de vida dos ovos","features":[{"title":"Painel de ovos","desc":"Contagens em tempo real: nos ninhos, enviados ao berçário, marcados para descarte.","alt":"Painel de Recolha de ovos: 6 ovos recolhidos hoje, 50 no ninho, 21 para o berçário e 5 a descartar, com a lista Ovos no ninho"},{"title":"Registro de ovos (ninho / berçário)","desc":"Adicione ovos com progenitores, condição, datas, espécie, observações e anexos.","alt":"Formulário Adicionar ovos com recinto, parentesco e local do ovo"},{"title":"Acompanhamento do ciclo de vida","desc":"Status, peso e a linha do tempo completa da jornada do ovo.","alt":"Linha do tempo da jornada do ovo: eclodido, incubação natural"},{"title":"Incubação natural","desc":"Ovos incubados nos ninhos: ID, data de coleta, condição.","alt":"Painel de Recolha de ovos: 6 ovos recolhidos hoje, 50 no ninho, 21 para o berçário e 5 a descartar, com a lista Ovos no ninho"},{"title":"Incubação artificial","desc":"Ovos no berçário: avaliar, levar para incubação, descartar ou registrar eclosão.","alt":"Lista Ovos para o berçário: entradas de crocodilo-de-água-salgada com caixas para selecionar tudo"},{"title":"Transferências de ovos","desc":"Acompanhe unidade, estágio, data de eclosão, espécie, ID e sexo.","alt":"Ovos transferidos: pedidos de transferência em lote com estados Cancelado e pendente"},{"title":"Descarte de ovos","desc":"Descarte ovos inviáveis com o motivo registrado e trilha de auditoria.","alt":"Separador Ovos a descartar: 36 ovos a descartar, cada um com espécie, ID do ovo, data, motivo como Podre e uma caixa de seleção"},{"title":"Criar ID do animal","desc":"Gere um registro para os ovos eclodidos, vinculado à espécie e aos progenitores.","alt":"Separador Ovos eclodidos: 4 ovos eclodidos, com Criar ID do animal em ovos de crocodilo-de-água-salgada e uma arara-azul-grande já com o ID 422163"}]},"egg-management-web":{"title":"Gestão de Ovos — Web","intro":"O complemento web da Gestão de Ovos, usado por supervisores e responsáveis pelo berçário para configurar incubadoras, gerar relatórios e acompanhar os ovos em cada etapa do ciclo de vida. Rastreabilidade completa, visualizações filtráveis e relatórios exportáveis para conformidade e revisão.","summary":"Usado por supervisores e responsáveis pelo berçário para configurar incubadoras, gerar relatórios e acompanhar os ovos","features":[{"title":"Configuração de berçários e incubadoras","desc":"Configure berçários vinculados às unidades, crie salas e gerencie incubadoras.","alt":"Lista de berçários na web: berçários com salas, incubadoras, local e estado Ativo, com pesquisa, filtro de local e Adicionar novo"},{"title":"Relatórios, filtros e acesso aos dados","desc":"Filtre por unidade, espécie, data ou estágio; exporte relatórios.","alt":"Painel Estatísticas de ovos na web: ovos no ninho, para o berçário, eclodidos, descartados e total, com os separadores Ovos por espécie, local e berçário e Transferir"},{"title":"Lista de ovos","desc":"Abas por status: Recebidos, Em incubação, Eclodidos, Descartados, Todos.","alt":"Lista de ovos na web: separadores Recebidos, Incubação, Eclodidos, A descartar, Descartados e Todos, com espécie, identificador do ovo e estado"}]},"announcement":{"title":"Comunicados","intro":"O Módulo de Comunicados é a ferramenta centralizada para compartilhar atualizações importantes e avisos gerais entre equipes e locais. Ele permite comunicação direcionada, agendamento e interação, garantindo que a mensagem certa chegue às pessoas certas no momento certo.","summary":"Ferramenta centralizada para compartilhar atualizações importantes e avisos gerais entre equipes e locais","features":[{"title":"Tipos de comunicado","desc":"Geral e Importante, cada um com suas próprias regras de visibilidade.","alt":"Formulário Criar aviso com o seletor de tipo Geral e Importante destacado"},{"title":"Listagem unificada","desc":"Todos os comunicados em uma única visualização, os seus separados dos demais.","alt":"Detalhe do comunicado: Every Move Counts, com imagem anexada"},{"title":"Criar comunicados","desc":"Defina tipo, título e visibilidade; publique ou agende; pré-visualize e anexe arquivos.","alt":"Formulário Criar aviso com tipo, detalhes, visibilidade e agendamento"},{"title":"Ações após a publicação","desc":"Edite, cancele ou exclua comunicados. As notificações e a tela inicial os mantêm visíveis para as pessoas certas.","alt":"Detalhe de comunicado geral com o menu Editar, Cancelar, Excluir aberto"}]},"helpdesk-module":{"title":"Módulo Central de Ajuda","intro":"O Módulo de Solicitações ajuda a equipe do zoológico a abrir e acompanhar solicitações de recursos, manutenção ou serviços, garantindo responsabilização, resolução mais rápida e melhor coordenação entre departamentos. Substitui e-mails e formulários de papel por uma trilha única e auditável.","summary":"Abra e acompanhe solicitações de recursos, manutenção ou serviços, com melhor coordenação entre departamentos","features":[{"title":"Ver solicitações por status","desc":"Pendente, Aprovada, Rejeitada, Cancelada, Em andamento, Concluída.","alt":"Lista da central de ajuda com as abas Aguardando aprovação, Aprovadas, Rejeitadas, Canceladas"},{"title":"Gestão de solicitações","desc":"Abra, edite, cancele ou rejeite solicitações com prioridades.","alt":"Pedido de carpintaria de caixas-ninho de madeira em South Aviary Dome: fornecedor, detalhes do pedido, custo estimado, custo real e estado atual Em andamento"},{"title":"Gestão de custos","desc":"Adicione, edite, duplique ou exclua estimativas de custo por item.","alt":"Detalhamento de custos: itens Telhado e Madeira"},{"title":"Atendimento e reversão","desc":"Marque solicitações como atendidas ou devolva-as para Em andamento.","alt":"Pedido REQ29-00172 de reparação de uma cerca de madeira, marcado como Pedido concluído pela autoridade, com Voltar para Em andamento"}]},"security":{"title":"Segurança","intro":"O Módulo de Segurança gerencia as permissões específicas de cada unidade e supervisiona os processos de transferência e descarte de ovos e qualquer transferência de animais ou para o hospital, garantindo movimentação controlada e total responsabilização sobre quem manuseou o quê e quando.","summary":"Gerencia permissões por unidade e supervisiona transferências de ovos, animais e para o hospital, com total responsabilização","features":[{"title":"Filtros","desc":"Filtre os registros por status: Mostrar todos, Saída pendente ou Saída liberada pela segurança, para uma revisão focada.","alt":"Caixa de diálogo Filtrar por: Mostrar todos, Saída pendente, Saída liberada pela segurança"},{"title":"Entrada e saída","desc":"A equipe de segurança autorizada registra a entrada e a saída nas transferências de ovos, de animais e para o hospital.","alt":"Transferência INT-02997 com o botão Saída pela segurança (“Security Checkout”)"}]},"reports-app":{"title":"Relatórios - App","intro":"O Módulo de Relatórios apresenta dados categorizados sobre os principais eventos dos animais, organizados em títulos específicos para análises rápidas em qualquer lugar.","summary":"Dados categorizados sobre os principais eventos dos animais, para análises rápidas em qualquer lugar","features":[{"title":"Filtros","desc":"Refine os relatórios por data, unidade ou espécie.","alt":"Relatório de principais análises: filtro Dia/Semana/Mês, data, Natalidade e detalhamento por espécie"},{"title":"Estatísticas","desc":"Filtragem por data e estatísticas por categoria: Natalidade, Mortalidade, Novas chegadas, Transferências entre unidades (entrada/saída), Externas, Transferências internas e Desperdício de alimentos.","alt":"Seletor de categorias de estatísticas: Natalidade, Mortalidade, Novas chegadas, Transferências entre unidades, Transferência externa"}]},"reports-web":{"title":"Relatórios (Web)","intro":"O complemento web gera relatórios claros e para download sobre dados e atividades dos animais, abrangendo nascimentos, óbitos, transferências e avaliações, com base nos mesmos registros do aplicativo.","summary":"Gera relatórios claros e para download sobre dados e atividades dos animais","features":[{"title":"Filtros e pesquisa","desc":"Refine os relatórios por data, unidade ou espécie.","alt":"Relatório geral de espécies com o filtro Selecionar local destacado"},{"title":"Relatórios para download","desc":"Gere, visualize e baixe os relatórios de Espécies, Diário, Lista de animais, Avaliação de animais, Tratador, Usuário, Observação, Diário do tratador, Diário do biólogo e Contagem por recinto, para conformidade e acesso offline.","alt":"Relatório geral de espécies com o botão Transferir relatório destacado"}]},"lab":{"title":"Laboratório","intro":"O Módulo de Laboratório centraliza os registros e resultados de exames diagnósticos, agiliza os fluxos entre veterinários e laboratórios, apoia a detecção e o tratamento precoces de doenças e mantém um repositório digital seguro para biossegurança, auditorias e análises.","summary":"Centraliza registros e resultados de exames diagnósticos e agiliza os fluxos entre veterinários e laboratórios","features":[{"title":"Lista e filtragem de solicitações","desc":"Veja e filtre as solicitações de exames por laboratório, pesquisa ou status (Pendente, Em andamento, Concluída), com ícones coloridos.","alt":"Uma cientista trabalhando com um microscópio."},{"title":"Visualização detalhada da solicitação","desc":"Veja o solicitante, o animal, a unidade e o registro médico vinculado; atualize o status em tempo real, com sincronização automática entre os módulos.","alt":""},{"title":"Local e controle de acesso","desc":"Associe laboratórios a locais; gerencie quem pode configurar ou ver os dados do laboratório.","alt":""},{"title":"Mapeamento de exames por unidade","desc":"Atribua laboratórios a exames diagnósticos específicos diretamente na aba de configuração (“Config”) da unidade.","alt":""},{"title":"Atribuição individual e em massa","desc":"Associe laboratórios a cada exame ou atribua todos os exames a um laboratório padrão com um clique.","alt":""},{"title":"Gestão de exames e amostras","desc":"Crie e gerencie exames, subexames e tipos de amostra (soro, LCR etc.) e associe-os aos laboratórios certos.","alt":""},{"title":"Atualizar status do exame","desc":"Acompanhe as etapas: Aguardando amostra → Amostra recebida / rejeitada / coagulada / hemolisada / insuficiente → Em andamento → Concluído (Positivo / Negativo / Detectado / Não detectado / Inconclusivo).","alt":""},{"title":"Reatribuição de laboratório","desc":"Transfira exames para outros laboratórios quando necessário, sem interromper o fluxo de trabalho.","alt":""}]},"diet":{"title":"Dieta","intro":"O Módulo de Dieta é uma plataforma centralizada para o planejamento e a gestão eficientes das dietas dos animais. Ele permite que as equipes de nutrição montem planos alimentares estruturados usando componentes, ingredientes, tipos de alimento, receitas e combinações configuráveis, e programem as refeições por horário, dia ou fase de vida.","summary":"Plataforma centralizada para planejar e gerenciar com eficiência as dietas dos animais","features":[{"title":"Configuração da dieta","desc":"Crie dietas usando tipos de alimento, itens, receitas e misturas; programe refeições por horário, dia ou fase de vida; atribua por espécie ou por animal; ative, clone ou atribua dietas; anexe referências.","alt":"Uma variedade de frutas frescas preparadas como alimento para animais."},{"title":"Tipos de preparo e tamanho do corte","desc":"Crie e gerencie métodos de preparo para itens, receitas e combinações, garantindo consistência nutricional e de textura.","alt":""},{"title":"Tipos de alimento","desc":"Lista centralizada e pesquisável de categorias de alimento, para um planejamento de dietas consistente.","alt":""},{"title":"Itens","desc":"Adicione, edite e exclua componentes da dieta com descrições detalhadas e imagens.","alt":""},{"title":"Receitas e misturas","desc":"Receitas e misturas com vários ingredientes: receitas por quantidades específicas, misturas por porcentagem de cada item, com componentes reutilizáveis e registros de atividade completos.","alt":""},{"title":"Grupos de refeição","desc":"Agrupe recintos para horários de alimentação e atribuições de dieta coordenados, com filtros por unidade, setor e espécie.","alt":""}]},"pharmacy-app":{"title":"Farmácia (App)","intro":"Permite a dispensação rápida, precisa e rastreável de produtos médicos diretamente aos médicos autorizados, garantindo atendimento no prazo e atualização automática do estoque.","summary":"Dispensação rápida, precisa e rastreável de produtos médicos diretamente aos médicos autorizados","features":[{"title":"Solicitação pelo aplicativo","desc":"Permite que os usuários solicitem produtos à farmácia diretamente pelo aplicativo.","alt":"Lista de pedidos: 11 pedidos com ID, farmácia, data, requerente e número de itens pedidos"},{"title":"Dispensação pelo aplicativo","desc":"Permite que o almoxarifado dispense produtos da farmácia diretamente pelo aplicativo.","alt":"Lista de dispensas: 14 dispensas com ID, farmácia, data, animal, medicamentos e quantidade total, e o botão Nova dispensa"}]},"pharmacy-web":{"title":"Farmácia (Web)","intro":"Permite a dispensação rápida, precisa e rastreável de produtos médicos diretamente aos médicos autorizados, garantindo atendimento no prazo e atualização automática do estoque, da prescrição até a prateleira, com visibilidade por lote e controle de validade em todas as etapas.","summary":"Dispensação rápida, precisa e rastreável de produtos médicos diretamente aos médicos autorizados","features":[{"title":"Painel","desc":"Tenha uma visão rápida do estoque, das remessas, das compras, das solicitações e das tendências dos produtos.","alt":"Painel da Farmácia: valor dos medicamentos vencidos, medicamentos sem estoque, total de solicitações, valor expedido, remessas, solicitações de hoje e gráfico mensal de expedições"},{"title":"Gestão de relatórios de estoque","desc":"Tenha uma visão consolidada do estoque por lote, dos itens com estoque baixo, dos produtos vencidos e a vencer, e dos produtos em custódia ou em divergência.","alt":"Relatório de estoque: lista de produtos por lote com quantidade no almoxarifado, preço unitário líquido e valor"},{"title":"Gestão de solicitações e devoluções de produtos","desc":"Gerencie solicitações de produtos, necessidades de cada almoxarifado, itens pendentes, expedições diretas e devoluções de produtos em uma visão centralizada.","alt":"Lista de solicitações de devolução de produtos com pesquisa e filtros por almoxarifado e por dias"},{"title":"Remessas","desc":"Veja e acompanhe as movimentações de estoque da farmácia, de entrada e de saída.","alt":"Remessas de saída: ID da remessa, tipo, destinatário, veículo e entregador"},{"title":"Dispensar medicamentos","desc":"Gerencie e acompanhe a dispensação dos medicamentos prescritos.","alt":"Lista de dispensas: ID da dispensa, número de animais, data e recebido por"},{"title":"Gestão de produtos","desc":"Gerencie produtos, estoque, compras, expedições, movimentações de estoque, substitutos, variantes e informações de referência em um só lugar.","alt":"Lista de produtos: todos os produtos com apresentação e fabricante"},{"title":"Gestão de entradas de estoque","desc":"Adicione, importe e confira entradas de estoque com dados de fornecedor, nota fiscal, lote, validade, preço e quantidade, mantendo registros e resumos completos das compras.","alt":"Lista de estoque com os botões Importar e Adicionar estoque, filtro por fornecedor e registros de compras"},{"title":"Gestão de ajustes de estoque","desc":"Gerencie ajustes de estoque e devoluções a fornecedores para manter o estoque correto, reduzir perdas e garantir rastreabilidade completa.","alt":"Lista de ajustes de estoque: abas extraviados/vencidos/danificados com produto, número do lote, quantidade, motivo e validade"},{"title":"Gestão de relatórios","desc":"Acompanhe e analise consumo, devoluções, remessas, dispensações, compras e solicitações com relatórios detalhados e filtráveis, para mais visibilidade do estoque e para auditorias.","alt":"Relatório de consumo com período, pesquisa, download e lista de produtos"},{"title":"Devolver produtos ao fornecedor","desc":"Devolva aos fornecedores produtos indesejados, vencidos, danificados ou em excesso, acompanhando quantidades, motivos e status da devolução.","alt":"Lista de devoluções ao fornecedor com número da solicitação, fornecedor, quantidade total e data de descarte"},{"title":"Gestão de cadastros, estantes e prateleiras","desc":"Organize os produtos por estantes e prateleiras e gerencie cadastros personalizáveis para um armazenamento e uma gestão de estoque eficientes.","alt":"Localização do estoque: configuração de estantes e prateleiras nos cadastros, com nome do produto, número de estantes e número de prateleiras"}]},"compliance":{"title":"Conformidade","intro":"O Módulo de Conformidade oferece uma visão da gestão de animais em nível de organização, abrangendo vários abrigos, fundos e fundações no aplicativo, e dá acesso aos registros de Exportação, Importação, Remessas e Espécies, mantendo toda a documentação regulatória em um único local confiável e disponível para download.","summary":"Visão da gestão de animais por organização e acesso aos registros de Exportação, Importação, Remessas e Espécies","features":[{"title":"Visão geral das organizações","desc":"Todas as organizações cadastradas no sistema, em uma única visualização.","alt":"Uma área de conservação com várias instalações."},{"title":"Contagens de espécies e animais","desc":"Número de espécies e total de animais de cada organização.","alt":""},{"title":"Cobertura de unidades","desc":"Número de unidades que gerenciam animais em cada organização.","alt":""},{"title":"Transparência e responsabilização","desc":"Relatórios precisos e visibilidade das populações de animais em todas as organizações.","alt":""},{"title":"Filtros e download","desc":"Filtre e baixe documentos com base em um período selecionado.","alt":""},{"title":"Exportação e importação","desc":"Registre e edite formulários de licença para animais exportados para ou importados de outro país ou instituição.","alt":""},{"title":"Remessa","desc":"Acompanhe os detalhes da remessa: meio de transporte, data de envio, contêineres, logística.","alt":""},{"title":"Espécies","desc":"Veja e baixe informações sobre as espécies envolvidas na transação (aves, mamíferos, répteis).","alt":""},{"title":"Configuração mestre","desc":"Configure tipos de documento e mantenha listas de importadores e exportadores para os registros de exportação/importação.","alt":""}]}}};
